{"rob": "robolang 1.3;

task transfer(robot r, object o, location src, location dst) {
    @safety max_speed 0.5 rad/s;
    goal { object_at o dst; }
    plan {
        move r to src;
        grasp r o;
        move r to dst;
        place r o at dst;
    }
}
